<template>
  <div id="test">
    <div id="main-title">נראה כמה באמת למדתם..</div>
    <div id="sub-title">תרגול</div>

    <multiple-choice 
      v-for="question in allQuestions"
      :key="question.id"
      :questionNum="question.id"
      :showResults="showResults"
      @answer-selected="handleAnswerSelected"
    />

    <div id="cheak" @click="checkAnswers">בדוק אותי</div>
    <div id="button" @click="nextPage">סיימתי</div>
  </div>
</template>

<script>
import MultipleChoice from "./MultipleChoice.vue";
import json from "../../text.json";

export default {
  name: "test",
  components: { MultipleChoice },
  data() {
    return {
      showResults: false,
      userAnswers: {},
    };
  },
  computed: {
    allQuestions() {
      // יוצר מערך של אובייקטי שאלות עם id
      return json.multipleChoice.map((q, index) => ({ ...q, id: index }));
    },
  },
  methods: {
    handleAnswerSelected({ questionNum, selected }) {
      this.$set(this.userAnswers, questionNum, selected);
    },
    checkAnswers() {
      // בודק אם מספר התשובות שנבחרו שווה למספר השאלות הכולל
      if (Object.keys(this.userAnswers).length < this.allQuestions.length) {
        alert("ישנן שאלות שעדיין לא ענית עליהן.");
        return; // עוצר את המשך הפונקציה
      }
      
      // אם כל השאלות נענו, ממשיך להצגת התוצאות
      this.showResults = true;
    },
    nextPage() {
      // עליך להחליט מה קורה בלחיצה על "סיימתי"
      this.$emit("next-page");
    },
  },
};
</script>

<style scoped>
#test {
  margin: 0%;
  overflow-x: hidden;
  height: 100%;
  width: 100vw;
  position: absolute;
  top: 0;
  right: 0;
  z-index: 3;
}

#main-title,
#sub-title {
  color: #f6f7e8;
  text-shadow: 10px -2px 10px rgba(0, 0, 0, 0.5);
  font-family: "asakim";
  margin-right: 2%;
}

#main-title {
  font-size: 8vw;
  margin-top: 24%;
}

#sub-title {
  font-size: 12vw;
  margin-top: 2%;
}

#button {
  margin-top: 5vh;
  margin-bottom: 5vh;
  position: relative;
  right: 30%;
  font-family: "asakim";
  color: #f6f7e8;
  background-color: #7FCD91;
  border-radius: 1.5vh;
  padding: 3%;
  width: 35vw;
  font-size: 9vw;
  font-weight: 570;
  text-align: center;
  box-shadow: rgba(34, 34, 38, 0.2) 0px 7vw 29vw 0px;
  cursor: pointer;
}

#cheak {
  margin-top: 5vh;
  margin-bottom: 5vh;
  position: relative;
  right: 35%;
  font-family: "asakim";
  color: #f6f7e8;
  background-color: #404341;
  border-radius: 1.5vh;
  padding: 3%;
  width: 25vw;
  font-size: 7vw;
  font-weight: 570;
  text-align: center;
  box-shadow: rgba(34, 34, 38, 0.2) 0px 7vw 29vw 0px;
  cursor: pointer;
}

@keyframes scaling {
  from {
    transform: scale(1);
  }
  to {
    transform: scale(1.1);
  }
}
</style>