<template>
  <div id="multiple-choice">
    <div class="question-container">
      <div class="question-text">{{ title }}</div>
      <div class="answers">
        <div
          v-for="(answer, index) in answers"
          :key="index"
          :id="index"
          class="answer"
          @click="selectAnswer(index)"
          :class="{ selected: selectedAns === index }"
          :style="answerStyle(index)"
        >
          {{ answer }}
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import json from "../../text.json";
export default {
  name: "multiple-choice",
  props: ["questionNum", "showResults"],
  data() {
    return {
      selectedAns: -1,
    };
  },
  computed: {
    title() {
      return json.multipleChoice[this.questionNum].title;
    },
    answers() {
      return json.multipleChoice[this.questionNum].answers;
    },
    correctAns() {
      return json.multipleChoice[this.questionNum].correctAns;
    },
  },
  methods: {
    selectAnswer(index) {
      if (!this.showResults) {
        this.selectedAns = index;
        this.$emit('answer-selected', { questionNum: this.questionNum, selected: index });
      }
    },
    answerStyle(index) {
      if (this.showResults) {
        if (index === this.correctAns) {
          return { backgroundColor: 'rgb(179, 241, 160)', boxShadow: 'rgba(0, 0, 0, 0.35) 0px 5px 15px' };
        } else if (index === this.selectedAns) {
          return { backgroundColor: 'rgb(247, 83, 83)', boxShadow: 'rgba(0, 0, 0, 0.35) 0px 5px 15px' };
        } else {
          return { backgroundColor: '#f6f7e8' };
        }
      } else if (this.selectedAns === index) {
        return { boxShadow: '#001d3d94 0px 0px 1.5vh' };
      }
      return { backgroundColor: '#f6f7e8' };
    },
  },
};
</script>

<style scoped>
#multiple-choice {
  margin: 0;
  height: fit-content;
  margin-bottom: 6%;
  width: 100vw;
  position: relative;
  top: 0;
  right: 0;
  display: flex;
  flex-direction: column;
  flex-wrap: nowrap;
  align-items: center;
}

.question-container {
  display: flex;
  height: fit-content;
  flex-direction: column;
  flex-wrap: nowrap;
  justify-content: center;
  overflow: hidden;
  margin: auto;
}

.question-text {
  padding: 2vh;
  padding-bottom: 20vh;
  border-radius: 1vh;
  background: #cdcec7;
  color: #001d3d;
  width: 75vw;
  margin-top: 2%;
  font-size: 8vw;
  font-family: "asakim";
  text-align: center;
}

.answers {
  display: flex;
  width: 75vw;
  flex-direction: column;
  flex-wrap: nowrap;
  justify-content: center;
  overflow-x: hidden;
  margin: auto;
  margin-top: -38%;
  background: #7fcd91;
  border-radius: 1vh;
  padding: 2%;
  box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px;
}

.answer {
  background-color: #cdcec7;
  color: #001d3d;
  font-size: 5vw;
  font-weight: 600;
  padding: 2%;
  border-radius: 0.5vh;
  margin: 1.5%;
  font-family: "assistant";
  cursor: pointer;
}

.selected {
  /* הסגנון הדינמי מטופל ב-answerStyle */
}
</style>